-- ─────────────────────────────────────────────────────────────────────
-- The catalogue stops being a sample.
--
-- Thirty-four seeded lifts is a demo, not a catalogue: somebody wanting an
-- exercise that is not in it has to add it before they can plan with it, which
-- is friction on the one screen that has to be fast. This imports 876 from the
-- Free Exercise DB, which is released into the public domain:
--
--   https://github.com/yuhonas/free-exercise-db  ·  The Unlicense
--
-- **The data only, deliberately not the images.** That dataset ships two
-- photographs per exercise and they are photographs of people in gyms. Merit
-- draws a silhouette with the worked muscles filled in instead — always
-- present, always the same, painted from the app's own tokens, and it answers
-- what somebody actually scans a catalogue for. `image_url` stays null and
-- stays available for the day a set of schematics exists.
--
-- Two columns arrive with it. `muscle_group` was one coarse value per exercise
-- and it stays, because eight groups is what the catalogue is filtered by
-- (§10.11) and seventeen is a list nobody reads. The finer muscles go beside
-- it, because the silhouette needs them.
--
-- Names are imported in English into both columns. Machine-translating nine
-- hundred exercise names would put a wrong German name on the screen, which is
-- worse than an English one — half of them are said in English in a German gym
-- anyway — and the catalogue is shared, so a correction by one person fixes it
-- for everyone.
-- ─────────────────────────────────────────────────────────────────────

alter table public.exercises
  add column primary_muscles   text[] not null default '{}',
  add column secondary_muscles text[] not null default '{}';

comment on column public.exercises.primary_muscles is
  'Muscles the lift is mainly for, in the catalogue vocabulary. Drives the silhouette.';

-- The existing thirty-four carry a group but no muscles. Rather than guess at
-- them one by one, the coarse group seeds the fine list: a chest exercise
-- lights the chest, which is true if imprecise, and the import below corrects
-- every one that turns out to be in the dataset too.
update public.exercises set primary_muscles = case muscle_group
  when 'chest'     then array['chest']
  when 'back'      then array['lats']
  when 'shoulders' then array['shoulders']
  when 'arms'      then array['biceps', 'triceps']
  when 'legs'      then array['quadriceps', 'hamstrings']
  when 'glutes'    then array['glutes']
  when 'core'      then array['abdominals']
  else array['abdominals', 'quadriceps', 'lats']
end
where primary_muscles = '{}';

insert into public.exercises
  (name_en, name_de, muscle_group, equipment, primary_muscles, secondary_muscles, source)
